// Decorative SVGs share the local symbol set in index.html; labels stay in text.
const icon = name => '<svg class="icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><use href="#icon-' + name + '"></use></svg>';
const content = window.RABEN_CONTENT;
const el = (tag, text, className) => { const node=document.createElement(tag); node.textContent=text; if(className) node.className=className; return node; };
document.getElementById('about-text').textContent=content.about;
document.getElementById('year').textContent=new Date().getFullYear();
if(content.capabilities.length){const list=el('div','','capability-list');content.capabilities.forEach((item,i)=>{const card=el('article','','capability');card.append(el('span',String(i+1).padStart(2,'0'),'number'),el('h3',item.title),el('p',item.description));list.append(card)});document.getElementById('capabilities').append(list)}
const projects=document.getElementById('project-list');
if(!content.projects.length){projects.innerHTML='<div class="empty-projects"><div><h3>הפרק הבא יופיע כאן.</h3><p>כאן נציג את הפרויקטים שאנחנו בונים יחד ואת העבודה שלנו לעסקים. נוסיף כל פרויקט עם הסיפור שלו, תמונות וקישור כשיהיה מוכן להצגה.</p></div><span class="empty-symbol" aria-hidden="true">'+icon('asterisk')+'</span></div>'}else{content.projects.forEach(p=>{const card=el('article','','project-card');card.append(el('h3',p.title),el('p',p.description));if(p.url&&/^https?:\/\//.test(p.url)){const link=el('a','לצפייה בפרויקט','project-link');link.insertAdjacentHTML('beforeend',icon('arrow-up-right'));link.href=p.url;link.target='_blank';link.rel='noopener noreferrer';card.append(link)}projects.append(card)})}
const panel=document.getElementById('demo-panel');const descriptions={web:'איך שינוי קטן משנה את התחושה? בחרו צבע וראו את הממשק מתעדכן.',flow:'תהליך גדול מתחיל בצעדים קטנים. הפעילו הדמיה מקומית של שלושה שלבים.',data:'אותם נתונים, מבט אחר. הזיזו את המחוון וראו תרשים עם נתוני הדגמה.'};let flowTimer;
function renderDemo(type){clearTimeout(flowTimer);document.getElementById('demo-description').textContent=descriptions[type];panel.setAttribute('aria-labelledby','tab-'+type);document.querySelectorAll('[data-demo]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.demo===type)));
if(type==='web'){panel.innerHTML='<div class="demo-card" style="--accent:#145cf3"><div class="demo-top"><span>מרחב העבודה שלי</span><span>INTERFACE DEMO</span></div><h3>יום חדש. רעיון חדש.</h3><p>ממשק קטן עם מקום לדברים הגדולים.</p><div class="mini-grid"><div><strong>03</strong><span>רעיונות לדוגמה</span></div><div><strong>01</strong><span>צעד הבא</span></div></div><div class="demo-bottom"><div class="swatches" aria-label="בחירת צבע"><button aria-label="כחול" aria-pressed="true" style="--swatch:#145cf3" data-color="#145cf3"></button><button aria-label="סגול" aria-pressed="false" style="--swatch:#7c4ee4" data-color="#7c4ee4"></button><button aria-label="ירוק" aria-pressed="false" style="--swatch:#188b7b" data-color="#188b7b"></button></div><span>הצבע שלכם, התחושה שלכם</span></div></div>';panel.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{panel.querySelector('.demo-card').style.setProperty('--accent',b.dataset.color);panel.querySelectorAll('[data-color]').forEach(s=>s.setAttribute('aria-pressed',String(s===b)))})}
if(type==='flow'){panel.innerHTML='<div class="demo-card"><div class="demo-top"><span>מרעיון לתהליך</span><span>LOCAL SIMULATION</span></div><h3>צעד. ועוד צעד.</h3><p>הדמיית ממשק בלבד — ללא חיבור למערכת חיצונית.</p><div class="flow-steps"><div class="flow-step">קבלת רעיון</div>'+icon('arrow-left')+'<div class="flow-step">עיבוד</div>'+icon('arrow-left')+'<div class="flow-step">מוכן</div></div><button class="demo-run">להפעיל הדמיה '+icon('play')+'</button><p id="flow-status" role="status">מחכים לרעיון שלכם.</p></div>';const run=panel.querySelector('.demo-run');run.onclick=()=>{run.disabled=true;const steps=[...panel.querySelectorAll('.flow-step')];let i=0;function step(){steps[i].classList.add('active');panel.querySelector('#flow-status').textContent=['הרעיון התקבל בהדמיה.','מעבדים את הרעיון בהדמיה.','ההדמיה הושלמה. אפשר להתחיל שוב.'][i];i++;if(i<3){flowTimer=setTimeout(step,600)}else{run.disabled=false;run.innerHTML='להפעיל שוב '+icon('rotate')}}steps.forEach(s=>s.classList.remove('active'));step()}}
if(type==='data'){panel.innerHTML='<div class="demo-card"><div class="demo-top"><span>מבט על נתונים</span><span>SAMPLE DATA</span></div><h3>לראות את התמונה.</h3><p>נתונים לדוגמה, שנוצרים כאן בדפדפן.</p><div class="chart" aria-label="תרשים עמודות עם נתוני הדגמה">'+[35,60,45,80,65,100].map(v=>'<div class="bar" style="height:'+v+'%"></div>').join('')+'</div><label class="range-row" for="data-range">קנה מידה <input id="data-range" type="range" min="20" max="100" value="100"><output id="range-value">100%</output></label></div>';panel.querySelector('#data-range').oninput=e=>{const val=Number(e.target.value);panel.querySelector('#range-value').textContent=val+'%';panel.querySelectorAll('.bar').forEach((b,i)=>b.style.height=[35,60,45,80,65,100][i]*val/100+'%')}}}
document.querySelectorAll('[data-demo]').forEach((b,i,buttons)=>{b.onclick=()=>renderDemo(b.dataset.demo);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowLeft'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();renderDemo(buttons[next].dataset.demo)}}});renderDemo('web');
document.getElementById('brief-form').onsubmit=e=>{e.preventDefault();const name=document.getElementById('name').value.trim();const idea=document.getElementById('idea').value.trim();if(!idea){document.getElementById('idea').setCustomValidity('כתבו בכמה מילים את הרעיון שלכם.');document.getElementById('idea').reportValidity();return}document.getElementById('brief-output').value=`היי RABEN,${name?' אני '+name+'.':''}\n${document.getElementById('kind').value}\n\n${idea}`;document.getElementById('brief-result').hidden=false;document.getElementById('form-status').textContent='התקציר מוכן. אפשר להעתיק אותו — הוא לא נשלח.';};document.getElementById('idea').oninput=e=>e.target.setCustomValidity('');
document.getElementById('copy-brief').onclick=async()=>{const output=document.getElementById('brief-output');try{await navigator.clipboard.writeText(output.value);document.getElementById('form-status').textContent='התקציר הועתק ללוח.'}catch{output.focus();output.select();document.getElementById('form-status').textContent='בחרנו את הטקסט. אפשר להעתיק ידנית.'}};
